  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let node = power();
    for (let index = signs.length - 1; index >= 0; index -= 1) {
      node = { type: 'unary', operator: signs[index], operand: node };
    }
    return node;
  }

