'use strict';

const { ExprError } = require('./errors');

/** CPython's float divmod; zero results are normalized to positive zero. */
function divmod(left, right) {
  let mod = left % right;
  let div = (left - mod) / right;
  if (mod !== 0) {
    if ((right < 0) !== (mod < 0)) {
      mod += right;
      div -= 1;
    }
  }
  let floor = 0;
  if (div !== 0) {
    floor = Math.floor(div);
    if (div - floor > 0.5) floor += 1;
  }
  return [floor === 0 ? 0 : floor, mod === 0 ? 0 : mod];
}

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**':
      // Python: 1 ** y and (-1) ** ±inf are 1; JavaScript yields NaN.
      if (left === 1 || (left === -1 && !Number.isFinite(right) && !Number.isNaN(right))) return 1;
      return left ** right;
    case '//': return divmod(left, right)[0];
    case '%': return divmod(left, right)[1];
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

